import { describe, expect, it } from 'vitest';
import { NOTIFICATION_FEEDS, NotificationFeeds, releaseNotifications, type NotificationFeedsSnapshot } from './adapter.ts';

const PRO = [ 'elite', 'personal', 'plus', 'professional', 'ultimate' ];

function feeds( live: unknown[], draft: unknown[] = live ): Record<string, unknown> {
	return { [ NOTIFICATION_FEEDS.live ]: live, [ NOTIFICATION_FEEDS.draft ]: draft };
}

function fetcherFor( data: Record<string, unknown>, calls: string[] = [] ) {
	return async ( url: string ) => {
		calls.push( url );

		if ( data[ url ] instanceof Error ) {
			throw data[ url ];
		}

		return data[ url ];
	};
}

describe( 'NotificationFeeds', () => {
	it( 'reads both feeds and keeps only well-formed entries', async () => {
		const live = [ { id: 226, title: 'T', content: '<strong>WP Simple Pay 4.17.4</strong>', type: [ 'lite' ] }, { title: 'no id' }, null, 'junk' ];
		const snapshot = await new NotificationFeeds( fetcherFor( feeds( live ) ) ).lookup();

		expect( snapshot?.live ).toEqual( [ { id: 226, title: 'T', content: '<strong>WP Simple Pay 4.17.4</strong>', type: [ 'lite' ] } ] );
		expect( snapshot?.draft ).toHaveLength( 1 );
	} );

	it( 'reports unknown when a feed fails or is not a list, and does not cache that', async () => {
		const calls: string[] = [];
		const data = feeds( [] );
		data[ NOTIFICATION_FEEDS.draft ] = new Error( 'HTTP 503' );
		const lookups = new NotificationFeeds( fetcherFor( data, calls ) );

		expect( await lookups.lookup() ).toBeNull();
		data[ NOTIFICATION_FEEDS.draft ] = { not: 'a list' };
		expect( await lookups.lookup() ).toBeNull();
		data[ NOTIFICATION_FEEDS.draft ] = [];
		expect( await lookups.lookup() ).toEqual( { live: [], draft: [] } );
		expect( calls ).toHaveLength( 6 );
	} );

	it( 'caches a good lookup until it expires or is cleared', async () => {
		let now = 0;
		const calls: string[] = [];
		const lookups = new NotificationFeeds( fetcherFor( feeds( [] ), calls ), 1000, () => now );

		await lookups.lookup();
		await lookups.lookup();
		expect( calls ).toHaveLength( 2 );

		now = 2000;
		await lookups.lookup();
		expect( calls ).toHaveLength( 4 );

		lookups.clear();
		await lookups.lookup();
		expect( calls ).toHaveLength( 6 );
	} );
} );

describe( 'releaseNotifications', () => {
	const item = ( id: number, version: string, type: string[], pro = false ) => ( {
		id,
		title: '[NEW] Something',
		content: `<p><strong>WP Simple Pay ${ pro ? 'Pro ' : '' }${ version }</strong> adds things.</p>`,
		type,
	} );

	it( 'finds a release’s Pro and Lite notifications, drafts and published', () => {
		const snapshot: NotificationFeedsSnapshot = {
			live: [ item( 1, '4.17.4', [ 'lite' ] ), item( 2, '4.17.5', PRO, true ) ],
			draft: [ item( 1, '4.17.4', [ 'lite' ] ), item( 2, '4.17.5', PRO, true ), item( 3, '4.17.5', [ 'lite' ] ) ],
		};

		expect( releaseNotifications( snapshot, '4.17.5' ) ).toEqual( [
			{ id: 2, audience: 'pro', published: true },
			{ id: 3, audience: 'lite', published: false },
		] );
		expect( releaseNotifications( snapshot, '4.17.6' ) ).toEqual( [] );
	} );

	it( 'does not confuse a hotfix with its base version, but allows a full stop after it', () => {
		const snapshot: NotificationFeedsSnapshot = {
			live: [],
			draft: [ item( 4, '4.17.5.1', [ 'lite' ] ), { id: 5, title: 'x', content: 'Out now: WP Simple Pay 4.17.5. Enjoy.', type: [ 'lite' ] } ],
		};

		expect( releaseNotifications( snapshot, '4.17.5' ).map( ( found ) => found.id ) ).toEqual( [ 5 ] );
		expect( releaseNotifications( snapshot, '4.17.5.1' ).map( ( found ) => found.id ) ).toEqual( [ 4 ] );
	} );
} );
